"""Aggressive Cows — binary search on the minimum spacing.

"Can all k cows be placed at least d apart?" is answered greedily in O(n) and is
monotonic in d, so binary search finds the largest feasible d.

Time: O(n log n + n log(range))   Space: O(1)
"""
from typing import List


class Solution:
    def aggressiveCows(self, stalls: List[int], k: int) -> int:
        stalls.sort()

        def fits(distance: int) -> bool:
            placed, last = 1, stalls[0]
            for spot in stalls[1:]:
                if spot - last >= distance:
                    placed += 1
                    last = spot
                    if placed == k:
                        return True
            return placed >= k

        lo, hi, best = 1, stalls[-1] - stalls[0], 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if fits(mid):
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best
